LINES = {5: [('How long does a bullet take to cross an apple?', 'hook'), ('This apple is about three inches wide.', ''), ('A bullet flies about nineteen hundred miles an hour.', ''), ('So it crosses in less than a ten-thousandth of a second.', ''), ("Let's slow that down… ten thousand times.", ''), ('Now watch it drift in, like a slow fish.', ''), ('The skin dimples. And the far side blows outward, in a spray.', ''), ('Slow it five times more. Fifty thousand.', ''), ('The juice hangs in the air. The bullet is already past.', 'payoff'), ('A bullet is fast. But out the window, something is much faster. A storm.', 'cliff')], 6: [('Does lightning strike all at once?', 'hook'), ("Beyond the window, a storm. Let's slow it a thousand times.", ''), ('A faint path of charge creeps down from the cloud, in jumps.', ''), ('Each jump is about a hundred and fifty feet, and over in a millionth of a second.', ''), ('Slow it a thousand times more. A million. Now one jump lasts a whole second.', ''), ('Then it waits: fifty millionths of a second. Almost a minute here.', ''), ('Look at it branch, like a tree turned upside down.', ''), ('At last it touches the ground, and a bright flash runs back up.', 'payoff'), ('That flash climbs about sixty thousand miles a second. A third of the speed of light.', ''), ('Even a million times slower, it takes over thirty seconds to climb two miles.', ''), ("That's the fastest thing so far. But it's not light's top speed.", 'cliff')], 7: [('Light crosses a kitchen. Seventeen seconds.', 'hook'), ('Ten million times slower, one second lasts about four months.', ''), ('A hundred million times slower: more than three years.', ''), ('A billion times slower: about thirty-two years.', ''), ('Now light moves about a foot in one second.', ''), ('Someone flicks on a lamp. A soft front of light spreads across the room.', ''), ('Behind it, the table is lit. Ahead of it, still dark.', 'payoff'), ('It takes about seventeen seconds to reach the far wall.', ''), ('And in the corner, a computer chip is about to start ticking.', 'cliff')], 8: [('Is light slower than a snail?', 'hook'), ('A computer chip ticks about three billion times a second. Here, it ticks three times a second. Tick. Tick. Tick.', ''), ('Keep going. Ten billion times slower, and light moves about an inch a second.', ''), ('A hundred billion: about an eighth of an inch a second.', ''), ('A trillion times slower: about a hundredth of an inch a second. Slower than a garden snail.', ''), ('One second of your life now lasts about thirty-two thousand years.', ''), ('Light would take about four and a half hours to cross this room.', ''), ('Light crosses a human hair in about a third of a trillionth of a second. Here, about a third of a second.', 'payoff'), ('But has anyone ever filmed light crawling like this?', 'cliff')]}
